INSERT INTO `homepage_sections` VALUES (1,'hero','{\"ar\":\"┘╪ذ┘┘è\",\"en\":\"We build\"}','{\"ar\":\"┘╪╡┘à┘à ┘ê┘╪╖┘ê╪▒ ┘à┘╪╡╪د╪ز ┘ê┘è╪ذ╪î ╪ز╪╖╪ذ┘è┘é╪د╪ز ┘à┘ê╪ذ╪د┘è┘╪î ┘ê╪ث┘╪╕┘à╪ر ╪ث╪╣┘à╪د┘ ┘à╪«╪╡╪╡╪ر ╪ز╪│╪د╪╣╪» ╪د┘╪┤╪▒┘â╪د╪ز ╪╣┘┘ë ╪د┘╪╣┘à┘ ╪ذ┘â┘╪د╪ة╪ر ┘ê╪د┘┘┘à┘ê ╪ذ╪س┘é╪ر.\",\"en\":\"We design and develop web platforms, mobile applications, and custom business systems that help companies operate efficiently and grow with confidence.\"}','{\"cta_primary\": {\"url\": \"/contact\", \"label\": {\"ar\": \"╪د╪ذ╪»╪ث ┘à╪┤╪▒┘ê╪╣┘â\", \"en\": \"Start Your Project\"}}, \"description\": {\"ar\": \"┘╪╡┘à┘à ┘ê┘╪╖┘ê╪▒ ┘à┘╪╡╪د╪ز ┘ê┘è╪ذ╪î ╪ز╪╖╪ذ┘è┘é╪د╪ز ┘à┘ê╪ذ╪د┘è┘╪î ┘ê╪ث┘╪╕┘à╪ر ╪ث╪╣┘à╪د┘ ┘à╪«╪╡╪╡╪ر ╪ز╪│╪د╪╣╪» ╪د┘╪┤╪▒┘â╪د╪ز ╪╣┘┘ë ╪د┘╪╣┘à┘ ╪ذ┘â┘╪د╪ة╪ر ┘ê╪د┘┘┘à┘ê ╪ذ╪س┘é╪ر.\", \"en\": \"We design and develop web platforms, mobile applications, and custom business systems that help companies operate efficiently and grow with confidence.\"}, \"capabilities\": {\"web\": {\"ar\": \"WEB PLATFORMS\", \"en\": \"WEB PLATFORMS\"}, \"custom\": {\"ar\": \"CUSTOM SOFTWARE\", \"en\": \"CUSTOM SOFTWARE\"}, \"mobile\": {\"ar\": \"MOBILE APPS\", \"en\": \"MOBILE APPS\"}, \"systems\": {\"ar\": \"BUSINESS SYSTEMS\", \"en\": \"BUSINESS SYSTEMS\"}}, \"cta_secondary\": {\"url\": \"/work\", \"label\": {\"ar\": \"╪د╪│╪ز┘â╪┤┘ ╪ث╪╣┘à╪د┘┘╪د\", \"en\": \"Explore Our Work\"}}, \"eyebrow_brand\": {\"ar\": \"Yظ¤TECH / DIGITAL ENGINEERING\", \"en\": \"Yظ¤TECH / DIGITAL ENGINEERING\"}, \"headline_line2\": {\"ar\": \"╪ز╪«╪»┘à ╪ث╪╣┘à╪د┘┘ï╪د ╪ص┘é┘è┘é┘è╪ر.\", \"en\": \"for real businesses.\"}, \"image_media_id\": 5, \"eyebrow_tagline\": {\"ar\": \"┘ç┘╪»╪│╪ر ╪د┘┘à┘╪ز╪ش╪د╪ز ┘ê╪د┘╪ث┘╪╕┘à╪ر ╪د┘╪▒┘é┘à┘è╪ر\", \"en\": \"Digital products & systems engineering\"}, \"headline_line1_accent\": {\"ar\": \"┘à┘╪ز╪ش╪د╪ز ╪▒┘é┘à┘è╪ر\", \"en\": \"digital products\"}, \"headline_line1_prefix\": {\"ar\": \"┘╪ذ┘┘è\", \"en\": \"We build\"}}',1,1,'2026-08-30 17:49:36','2026-09-02 03:39:41'),(2,'clients