INSERT INTO `testimonials` VALUES (1,'Ahmed Al-Rashid','CEO','AlNoor Trading Co.','{\"ar\":\"╪ص┘ê┘ّ┘╪ز Ytech ╪ث╪╣┘à╪د┘┘╪د ╪د┘╪ز╪ش╪▓╪خ┘è╪ر ╪ذ┘à┘╪╡╪ر ╪ز╪ز╪╣╪د┘à┘ ┘à╪╣ ╪ت┘╪د┘ ╪د┘╪╖┘╪ذ╪د╪ز ┘è┘ê┘à┘è╪د┘ï. ┘┘ç┘à ┘╪▒┘è┘é┘ç┘à ╪│┘ê┘é┘╪د ┘ê┘é╪»┘ّ┘à┘ê╪د ╪ث┘â╪س╪▒ ┘à┘à╪د ╪ز┘ê┘é╪╣┘╪د.\",\"en\":\"Ytech transformed our retail business with a platform that handles thousands of orders daily. Their team understood our market and delivered beyond expectations.\"}',5,NULL,NULL,1,'published',1,'2026-08-30 17:49:36','2026-08-30 17:49:36',NULL),(2,'Dr. Sarah Al-Mutairi','Director of Operations','MedTrack Clinics','{\"ar\":\"╪ث╪ص╪»╪س ╪ز╪╖╪ذ┘è┘é MedTrack ╪س┘ê╪▒╪ر ┘┘è ╪╖╪▒┘è┘é╪ر ╪ص╪ش╪▓ ┘à╪▒╪╢╪د┘╪د ┘┘┘à┘ê╪د╪╣┘è╪». ┘é╪»┘à╪ز Ytech ┘à┘╪ز╪ش╪د┘ï ┘à╪╡┘é┘ê┘╪د┘ï ┘ê┘à┘ê╪س┘ê┘é╪د┘ï ┘┘è ╪د┘┘ê┘é╪ز ╪د┘┘à╪ص╪»╪» ┘ê╪╢┘à┘ ╪د┘┘à┘è╪▓╪د┘┘è╪ر.\",\"en\":\"The MedTrack app has revolutionized how our patients book appointments. Ytech delivered a polished, reliable product on time and within budget.\"}',5,NULL,NULL,1,'published',2,'2026-08-30 17:49:36','2026-08-30 17:49:36',NULL),(3,'Khalid Al-Otaibi','Operations Manager','Gulf Logistics Group','{\"ar\":\"╪«┘┘ّ┘╪ز ┘┘ê╪ص╪ر ╪ز╪ز╪ذ╪╣ ╪د┘╪ث╪│╪╖┘ê┘ ┘╪»┘è┘╪د ╪ز╪ث╪«┘è╪▒ ╪د┘╪ز╪│┘┘è┘à ╪ذ┘╪│╪ذ╪ر 35%. ┘â╪د┘ ┘╪▒┘è┘é Ytech ╪│╪▒┘è╪╣ ╪د┘╪د╪│╪ز╪ش╪د╪ذ╪ر ┘ê┘à╪ص╪ز╪▒┘╪د┘ï ┘ê┘à╪│╪ز╪س┘à╪▒╪د┘ï ╪ص┘é╪د┘ï ┘┘è ┘╪ش╪د╪ص┘╪د.\",\"en\":\"Our fleet tracking dashboard reduced delivery delays by 35%. The Ytech team was responsive, professional, and truly invested in our success.\"}',5,NULL,NULL,1,'published',3,'2026-08-30 17:49:36','2026-08-30 17:49:36',NULL),(4,'Fatima Al-Harbi','CTO','FinServe Capital','{\"ar\":\"┘â╪د┘ ╪د┘╪ث┘à╪د┘ ┘ê╪د┘╪د┘à╪ز╪س╪د┘ ╪║┘è╪▒ ┘é╪د╪ذ┘┘è┘ ┘┘╪ز┘╪د┘ê╪╢. ╪ذ┘╪ز Ytech ╪ذ┘ê╪د╪ذ╪ر ╪ز┘╪ذ┘è ┘à╪ز╪╖┘╪ذ╪د╪ز SAMA ┘à╪╣ ╪ز╪ش╪▒╪ذ╪ر ┘à╪│╪ز╪«╪»┘à ┘à┘à╪ز╪د╪▓╪ر.\",\"en\":\"Security and compliance were non-negotiable for us. Ytech built a portal that meets SAMA requirements while providing an excellent user experience.\"}',5,NULL,NULL,0,'published',4,'2026-08-30 17:49:36','2026-08-30 17:49:36',NULL);
